import heapq

lo, hi = [], []  # max-heap (negated), min-heap

def add(x):
    heapq.heappush(lo, -x)
    heapq.heappush(hi, -heapq.heappop(lo))
    if len(hi) > len(lo):
        heapq.heappush(lo, -heapq.heappop(hi))

def median():
    return -lo[0] if len(lo) > len(hi) else (hi[0] - lo[0]) / 2
